// Embeds src/visitor-script.js into src/visitor.ts as a string, so the plugin
// bundle can hand the file to the site owner. Runs before build, typecheck and tests.
import { readFileSync, writeFileSync } from "node:fs";

const js = readFileSync(new URL("../src/visitor-script.js", import.meta.url), "utf8");
const version = /SCRIPT_VERSION\s*=\s*(\d+)/.exec(js)?.[1];
if (!version) throw new Error("visitor-script.js must define SCRIPT_VERSION");
const out =
	"// Generated by scripts/embed.mjs from src/visitor-script.js. Do not edit.\n" +
	`export const SCRIPT_VERSION = ${version};\n` +
	`export const VISITOR_SCRIPT: string = ${JSON.stringify(js)};\n`;
writeFileSync(new URL("../src/visitor.ts", import.meta.url), out);
console.log(`embedded visitor script v${version} (${js.length} bytes)`);
